  auto PURPOSE__ = PURPOSE ? _fbb.CreateString(PURPOSE) : 0;
  auto ACCOUNTS__ = ACCOUNTS ? _fbb.CreateVector<::flatbuffers::Offset<WHAAccount>>(*ACCOUNTS) : 0;
  auto HOLDINGS__ = HOLDINGS ? _fbb.CreateVector<::flatbuffers::Offset<WHAHolding>>(*HOLDINGS) : 0;
  auto CHAINS__ = CHAINS ? _fbb.CreateVector<::flatbuffers::Offset<WHAChain>>(*CHAINS) : 0;
  auto CURRENCY__ = CURRENCY ? _fbb.CreateString(CURRENCY) : 0;
  auto ERRORS__ = ERRORS ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*ERRORS) : 0;
  auto ATTESTER_ID__ = ATTESTER_ID ? _fbb.CreateString(ATTESTER_ID) : 0;
  auto SIGNATURE__ = SIGNATURE ? _fbb.CreateVector<uint8_t>(*SIGNATURE) : 0;
  auto SIGNATURE_TYPE__ = SIGNATURE_TYPE ? _fbb.CreateString(SIGNATURE_TYPE) : 0;
  return CreateWHA(
      _fbb,
      ATTESTATION_ID__,
      SUBJECT_ID__,
      PURPOSE__,
      ACCOUNTS__,
      HOLDINGS__,
      CHAINS__,
      CURRENCY__,
      ATTESTED,
      TOTAL_VALUE,
      ERRORS__,
      AS_OF_MS,
      ATTESTER_ID__,
      SIGNATURE__,
      SIGNATURE_TYPE__);
